  1	// Cyrus R3 gameplay designers: EDIT WITHOUT REGENERATING. A parameter edit (cooldown, range, strength, sound, damage,
  2	// durations, chances, texts...) changes values in the design and recompiles; because every graph value is a config.yml
  3	// parameter, the recompile touches only config.yml (values + designer-values hash + config_version) and the README,
  4	// never a Java file. `diffCompiled` shows exactly which files changed. `planDesignEdit` is the deterministic (no AI)
  5	// recogniser for change requests that only tweak parameters ("set the void pull cooldown to 5 seconds and the pull
  6	// strength to 2"); anything it cannot parse completely goes to the normal model path. Pure: no I/O, no model call.
  7	import { compileDesigns, designParams, type CompileContext, type CompileOk, type Param } from "./compile";
  8	import { ItemDesignSchema, type ItemDesign } from "./spec";
  9	
 10	export type ParamEdit = { path: string; value: number | string };
 11	export type AppliedEdit = { path: string; label: string; from: number | string; to: number | string };
 12	export type EditResult = { ok: true; designs: ItemDesign[]; applied: AppliedEdit[] } | { ok: false; errors: string[] };
 13	
 14	export const describeParameters = (designs: ItemDesign[]): Param[] => designParams(designs);
 15	
 16	const camelKey = (s: string) => s.replace(/_([a-z])/g, (_, c: string) => c.toUpperCase());
 17	
 18	/** Navigate a relative ability path ("a0.n1", "a2.then0", "c1", "a3.if0") to its node. */
 19	function nodeAt(ab: Record<string, unknown>, rel: string[]): Record<string, unknown> | null {
 20	  let cur: Record<string, unknown> | null = null;
 21	  for (let i = 0; i < rel.length; i++) {
 22	    const seg = rel[i];
 23	    const m = /^(a|n|then|else|c|if)(\d+)$/.exec(seg);
 24	    if (!m) return null;
 25	    const idx = Number(m[2]);
 26	    const list = (m[1] === "a" ? ab.actions : m[1] === "c" ? ab.conditions : m[1] === "n" ? cur?.actions : m[1] === "then" ? cur?.then : m[1] === "else" ? cur?.else : cur?.if) as unknown[] | undefined;
 27	    if ((m[1] === "a" || m[1] === "c") && i !== 0) return null;
 28	    if (!Array.isArray(list) || !list[idx] || typeof list[idx] !== "object") return null;
 29	    cur = list[idx] as Record<string, unknown>;
 30	  }
 31	  return cur;
 32	}
 33	
 34	/** Set one parameter in a (cloned) design. Returns an error string or null. */
 35	function setInDesign(d: ItemDesign, path: string, value: number | string): string | null {
 36	  const parts = path.split(".");
 37	  if (parts[0] !== "items" || parts[1] !== d.id) return `${path} is not in ${d.id}`;
 38	  const rest = parts.slice(2);
 39	  const obj = d as unknown as Record<string, unknown>;
 40	  if (rest[0] === "abilities") {
 41	    const ab = (d.abilities as unknown as Record<string, unknown>[]).find((a) => a.id === rest[1]);
 42	    if (!ab) return `no ability ${rest[1]}`;
 43	    const tail = rest.slice(2);
 44	    if (tail.length === 1 && tail[0] === "cooldown_ticks") { ab.cooldownTicks = value; return null; }
 45	    if (tail[0] === "charges" && tail.length === 2) { const c = ab.charges as Record<string, unknown> | undefined; if (!c) return "no charges"; c[camelKey(tail[1])] = value; return null; }
 46	    if (tail[0] === "trigger" && tail.length === 2) { (ab.trigger as Record<string, unknown>)[camelKey(tail[1])] = value; return null; }
 47	    const node = nodeAt(ab, tail.slice(0, -1).flatMap((s) => s.split("."))) ;
 48	    if (!node) return `no node at ${tail.slice(0, -1).join(".")}`;
 49	    node[camelKey(tail[tail.length - 1])] = value;
 50	    return null;
 51	  }
 52	  if (rest[0] === "marks" && rest.length === 3) { const m = (d.marks as unknown as Record<string, unknown>[] | undefined)?.find((x) => x.name === rest[1]); if (!m) return `no mark ${rest[1]}`; m[camelKey(rest[2])] = value; return null; }
 53	  if (rest[0] === "passives" && rest.length === 3) { const i = Number(rest[1].slice(1)); const p = (d.passives as unknown as Record<string, unknown>[] | undefined)?.[i]; if (!p) return `no passive ${rest[1]}`; p[camelKey(rest[2])] = value; return null; }
 54	  if ((rest[0] === "loot" || rest[0] === "drops") && rest.length === 3) { const i = Number(rest[1].slice(1)); const acq = obj.acquisition as Record<string, unknown[]> | undefined; const l = acq?.[rest[0]]?.[i] as Record<string, unknown> | undefined; if (!l) return `no ${rest[0]} ${rest[1]}`; l[camelKey(rest[2])] = value; return null; }
 55	  return `${path} is not a designer parameter`;
 56	}
 57	
 58	/** Apply parameter edits (exact config paths) to designs. Every value is checked against the parameter's caps. */
 59	export function applyParameterEdits(designs: ItemDesign[], edits: ParamEdit[]): EditResult {
 60	  const params = new Map(designParams(designs).map((p) => [p.path, p]));
 61	  const out = designs.map((d) => structuredClone(d));
 62	  const errors: string[] = [];
 63	  const applied: AppliedEdit[] = [];
 64	  for (const e of edits.slice(0, 32)) {
 65	    const p = params.get(e.path);
 66	    if (!p) { errors.push(`${e.path} is not a parameter of this mod (structural changes need a normal build)`); continue; }
 67	    let v: number | string = e.value;
 68	    if (p.kind === "text" || p.kind === "sound") {
 69	      if (typeof v !== "string") { errors.push(`${e.path} needs text`); continue; }
 70	      if (p.kind === "sound" && !/^[a-z0-9_.-]+:[a-z0-9_.-]+(\/[a-z0-9_.-]+)*$/.test(v)) { errors.push(`${e.path}: "${v}" is not a namespaced sound key`); continue; }
 71	      if (v.length < (p.kind === "text" ? 1 : 3) || v.length > p.max) { errors.push(`${e.path}: text must be 1-${p.max} characters`); continue; }
 72	    } else {
 73	      if (typeof v !== "number" || !Number.isFinite(v)) { errors.push(`${e.path} needs a number`); continue; }
 74	      if (p.kind !== "num") v = Math.round(v);
 75	      if (v < p.min || v > p.max) { errors.push(`${e.path}: ${v} is outside ${p.min}-${p.max}`); continue; }
 76	    }
 77	    const d = out.find((x) => x.id === p.item)!;
 78	    const err = setInDesign(d, e.path, v);
 79	    if (err) { errors.push(err); continue; }
 80	    applied.push({ path: e.path, label: p.label, from: p.value, to: v });
 81	  }
 82	  if (errors.length) return { ok: false, errors };
 83	  for (const d of out) { const r = ItemDesignSchema.safeParse(d); if (!r.success) return { ok: false, errors: r.error.issues.slice(0, 5).map((i) => `${d.id}: ${i.path.join(".")}: ${i.message}`) }; }
 84	  return { ok: true, designs: out, applied };
 85	}
