 87	export type FileDiff = { path: string; status: "changed" | "added" | "removed"; before?: string; after?: string };
 88	export type CompiledDiff = { changed: FileDiff[]; unchanged: number; javaChanged: string[]; readmeChanged: boolean };
 89	
 90	export function diffCompiled(a: Pick<CompileOk, "files" | "readmeSha256">, b: Pick<CompileOk, "files" | "readmeSha256">): CompiledDiff {
 91	  const am = new Map(a.files.map((f) => [f.path, f.sha256])), bm = new Map(b.files.map((f) => [f.path, f.sha256]));
 92	  const changed: FileDiff[] = [];
 93	  let unchanged = 0;
 94	  for (const [p, h] of am) { if (!bm.has(p)) changed.push({ path: p, status: "removed", before: h }); else if (bm.get(p) !== h) changed.push({ path: p, status: "changed", before: h, after: bm.get(p) }); else unchanged++; }
 95	  for (const [p, h] of bm) if (!am.has(p)) changed.push({ path: p, status: "added", after: h });
 96	  changed.sort((x, y) => (x.path < y.path ? -1 : 1));
 97	  return { changed, unchanged, javaChanged: changed.filter((c) => c.path.endsWith(".java")).map((c) => c.path), readmeChanged: a.readmeSha256 !== b.readmeSha256 };
 98	}
