100	/** Edit + recompile against the previous compile (its config.yml drives config_version). Only the affected files differ. */
101	export function recompileWithEdits(previous: CompileOk, edits: ParamEdit[], ctx: Omit<CompileContext, "previousConfig">): { ok: true; result: CompileOk; diff: CompiledDiff; applied: AppliedEdit[] } | { ok: false; errors: string[] } {
102	  const e = applyParameterEdits(previous.designs, edits);
103	  if (!e.ok) return e;
104	  const prevCfg = previous.files.find((f) => f.path === "src/main/resources/config.yml")?.content;
105	  const r = compileDesigns(e.designs, { ...ctx, previousConfig: prevCfg });
106	  if (!r.ok) return { ok: false, errors: r.errors.map((x) => `${x.path}: ${x.message}`) };
107	  return { ok: true, result: r, diff: diffCompiled(previous, r), applied: e.applied };
108	}
