110	// --------------------------------------------------------------------------------------------- change-request parser
111	const ROLE_WORDS: [RegExp, string[]][] = [
112	  [/^(cooldown|cool ?down|recharge time)$/, ["cooldown"]],
113	  [/^(range|radius|reach|distance)$/, ["range"]],
114	  [/^(strength|power|force|pull strength|push strength|knockback|pull|push)$/, ["strength"]],
115	  [/^(damage|dmg)$/, ["damage"]],
116	  [/^(heal|healing|heal amount)$/, ["heal"]],
117	  [/^(duration|length)$/, ["duration"]],
118	  [/^(chance|probability|odds)$/, ["chance"]],
119	  [/^(sound|sfx|sound effect)$/, ["sound"]],
120	  [/^(charges?)$/, ["charges"]],
121	  [/^(speed|projectile speed|velocity)$/, ["speed"]],
122	  [/^(message|text)$/, ["text"]],
123	];
124	export type EditPlan =
125	  | { kind: "parameters"; edits: ParamEdit[]; summary: string[] }
126	  | { kind: "model"; reason: string; candidates?: string[] };
127	
128	const norm = (s: string) => s.toLowerCase().replace(/[_-]/g, " ").replace(/\s+/g, " ").trim();
129	
130	/**
131	 * Recognise a change request that ONLY tweaks parameters. Grammar per clause (clauses split by "and", ",", ";"):
132	 *   [set|change|make|increase|decrease|lower|raise|reduce] [the] [<item or ability name>] <role word> (to|=) <value> [s|sec|seconds|ticks|blocks|%]
133	 * Seconds are the default unit for cooldowns and durations (x20 ticks). Every clause must parse and resolve to exactly
134	 * one parameter (narrowed by the item/ability names in the clause), else the request goes to the model.
135	 */
136	export function planDesignEdit(text: string, designs: ItemDesign[]): EditPlan {
137	  const params = designParams(designs);
138	  if (!text || text.length > 400) return { kind: "model", reason: "empty or long request" };
139	  if (/\b(add|new|remove|delete|instead|also|another|when|if|make it (shoot|fire|summon)|texture|model|recipe|craft|rename)\b/i.test(text)) return { kind: "model", reason: "structural change" };
140	  const clauses = text.split(/\s*(?:\band\b|,|;)\s*/i).map((c) => c.trim()).filter(Boolean);
141	  if (!clauses.length || clauses.length > 6) return { kind: "model", reason: "no clauses" };
142	  const edits: ParamEdit[] = [];
143	  const summary: string[] = [];
144	  const names = designs.flatMap((d) => [{ item: d.id, ability: undefined as string | undefined, words: [norm(d.id), norm(d.name.text)] }, ...d.abilities.map((a) => ({ item: d.id, ability: a.id, words: [norm(a.id), norm(a.name)] }))]);
145	  let lastScope: typeof names = [];
146	  for (const raw of clauses) {
147	    const c = norm(raw).replace(/[.!?]+$/, "");
148	    const m = /^(?:(?:please )?(?:set|change|make|increase|decrease|lower|raise|reduce|put|adjust)\s+)?(?:the\s+)?(.+)\s+(?:to|=)\s+(.+)$/.exec(c);
149	    if (!m) return { kind: "model", reason: `could not read "${raw}"` };
150	    let subject = m[1].replace(/'s\b/g, "").trim();
151	    // the value comes from the RAW clause (sound keys and texts keep their case and underscores)
152	    const rawValue = (/^.*\s(?:to|=)\s+(.+?)[.!?]*$/i.exec(raw.trim())?.[1] ?? m[2]).trim();
153	    const valueText = m[2].trim();
154	    // scope words: item / ability names in the subject (longest first); a clause without one inherits the previous clause's
155	    let scope = names.filter((n) => n.words.some((w) => w && subject.includes(w)));
156	    for (const w of scope.flatMap((x) => x.words).filter(Boolean).sort((a, b) => b.length - a.length)) subject = subject.replace(w, " ");
157	    if (!scope.length) scope = lastScope; else lastScope = scope;
158	    subject = subject.replace(/\b(the|of|on|for|its|my)\b/g, " ").replace(/\s+/g, " ").trim();
159	    const role = ROLE_WORDS.find(([re]) => re.test(subject))?.[1];
160	    if (!role) return { kind: "model", reason: `"${raw}" is not a known parameter (${subject || "nothing"})` };
161	    let cands = params.filter((p) => role.includes(p.role) || (role.includes("charges") && p.path.endsWith(".charges.max")));
162	    const abScope = scope.filter((s) => s.ability);
163	    const itScope = scope.filter((s) => !s.ability);
164	    if (abScope.length) cands = cands.filter((p) => abScope.some((s) => s.item === p.item && s.ability === p.ability));
165	    else if (itScope.length) cands = cands.filter((p) => itScope.some((s) => s.item === p.item));
166	    // an ability's own cooldown beats set_cooldown params; one strength per pull/push node
167	    if (role.includes("cooldown") && cands.some((p) => p.path.endsWith(".cooldown_ticks"))) cands = cands.filter((p) => p.path.endsWith(".cooldown_ticks"));
168	    if (cands.length !== 1) return { kind: "model", reason: cands.length ? `"${raw}" matches ${cands.length} settings` : `"${raw}" matches no setting`, candidates: cands.map((p) => p.path).slice(0, 8) };
169	    const p = cands[0];
170	    let value: number | string;
171	    if (p.kind === "sound" || p.kind === "text") {
172	      value = p.kind === "sound" ? rawValue.replace(/\s+/g, "").toLowerCase() : rawValue.replace(/^["']|["']$/g, "");
173	    } else {
174	      const n = /^(-?\d+(?:\.\d+)?)\s*(s|sec|secs|seconds?|ticks?|blocks?|%|percent|hearts?)?$/.exec(valueText);
175	      if (!n) return { kind: "model", reason: `"${valueText}" is not a number` };
176	      let x = Number(n[1]);
177	      const unit = n[2] ?? "";
178	      if (p.kind === "ticks") x = /^tick/.test(unit) ? x : x * 20; // seconds by default
179	      else if (/^(%|percent)$/.test(unit)) x = x / 100;
180	      else if (/^heart/.test(unit)) x = x * 2;
181	      value = p.kind === "num" ? x : Math.round(x);
182	    }
183	    edits.push({ path: p.path, value });
184	    summary.push(`${p.label}: ${p.value} -> ${value}`);
185	  }
186	  return { kind: "parameters", edits, summary };
187	}
  1	// Cyrus Config Studio <-> gameplay designers: ONE param model. The designers (lib/cyrus/designer) already turn every
  2	// number, text and sound of a design into a config.yml parameter (`Param`: path, kind num|ticks|int|text|sound, caps);
  3	// `fromDesignerParams` maps those into ConfigSpec params so the studio edits designer mods with the same form,
  4	// validator and writer as every other mod. The designers' own compile output stays byte-identical (nothing here is
  5	// imported by them). `toDesignerEdits` turns a studio patch back into designer ParamEdits (exact config paths), so the
  6	// designs can be updated with the designers' own `applyParameterEdits` when the mod is rebuilt. Pure.
  7	import type { Param } from "../designer/compile";
  8	import { CONFIG_LIMITS, SOUND_KEY_RE, isConfigKey, validateConfigSpec, type ConfigParamInput, type ConfigSpec, type ConfigSpecInput } from "./spec";
  9	import type { Patch } from "./diff";
 10	import { humanize } from "./infer";
 11	
 12	const ROLE_UNIT: Record<string, string> = { damage: "hp", heal: "hp", range: "blocks", radius: "blocks" };
 13	
 14	export type FromDesignerResult = { ok: true; spec: ConfigSpec; skipped: string[] } | { ok: false; errors: string[] };
 15	
 16	/** Designer params (designParams / modParams output) -> a ConfigSpec. `command` = the plugin's command (/<command> reload). */
 17	export function fromDesignerParams(params: readonly Param[], o: { command: string; groupLabels?: Record<string, string> }): FromDesignerResult {
 18	  const groups = new Map<string, string>();
 19	  const skipped: string[] = [];
 20	  const out: ConfigParamInput[] = [];
 21	  for (const p of params) {
 22	    if (!isConfigKey(p.path)) { skipped.push(p.path); continue; }
 23	    const owner = p.owner ?? "item";
 24	    let gid = `${owner === "item" ? "" : `${owner}_`}${p.item}`.toLowerCase().replace(/[^a-z0-9_-]/g, "_").replace(/^[^a-z]+/, "").slice(0, 32) || "general";
 25	    if (!groups.has(gid) && groups.size >= CONFIG_LIMITS.groups) gid = [...groups.keys()][groups.size - 1];
 26	    if (!groups.has(gid)) groups.set(gid, o.groupLabels?.[p.item] ?? `${owner === "menu" ? "Menu " : owner === "quest" ? "Quest " : ""}${humanize(p.item)}`.slice(0, 60));
 27	    const label = p.label.length <= 60 ? p.label : `${p.label.slice(0, 57)}...`;
 28	    const base = { key: p.path, group: gid, label, ...(p.label.length > 60 ? { help: p.label.slice(0, 200) } : {}), applies: "reload" as const, tags: [p.role].filter((r) => /^[a-z][a-z0-9_-]{0,23}$/.test(r)) };
 29	    switch (p.kind) {
 30	      case "num": out.push({ ...base, type: "number", default: Number(p.value), min: p.min, max: p.max, ...(ROLE_UNIT[p.role] ? { unit: ROLE_UNIT[p.role] } : {}) }); break;
 31	      case "int": out.push({ ...base, type: "int", default: Math.round(Number(p.value)), min: Math.ceil(p.min), max: Math.floor(p.max) }); break;
 32	      case "ticks": out.push({ ...base, type: "duration", durationUnit: "ticks", default: Math.round(Number(p.value)), min: p.min, max: p.max }); break;
 33	      case "text": out.push({ ...base, type: "text", default: String(p.value), maxLength: Math.max(1, Math.min(CONFIG_LIMITS.textChars, p.max)) }); break;
 34	      case "sound": if (SOUND_KEY_RE.test(String(p.value))) out.push({ ...base, type: "sound-ref", default: String(p.value) }); else skipped.push(p.path); break;
 35	    }
 36	  }
 37	  if (!out.length) return { ok: false, errors: ["the designs have no settings"] };
 38	  const input: ConfigSpecInput = {
 39	    schemaVersion: 1, file: "config.yml", format: "yaml", category: "designer", reload: { command: `/${o.command} reload` },
 40	    groups: [...groups.entries()].map(([id, label], i) => ({ id, label, order: i })), params: out,
 41	  };
 42	  const v = validateConfigSpec(input);
 43	  return v.ok ? { ok: true, spec: v.spec, skipped } : { ok: false, errors: v.errors.slice(0, 10).map((e) => `${e.path}: ${e.message}`) };
 44	}
 45	
 46	/** A studio patch -> designer ParamEdits (same paths; values as the designers expect them). */
 47	export function toDesignerEdits(patch: Patch): { path: string; value: number | string }[] {
 48	  return patch.filter((op) => typeof op.to === "number" || typeof op.to === "string").map((op) => ({ path: op.key, value: op.to as number | string }));
 49	}

  1	// Cyrus R3 gameplay designers, part 2: EDIT WITHOUT REGENERATING for menus and quests. Every number and text of a menu
  2	// or quest is a config.yml parameter (./compile.ts menuParams / questParams), so a value edit (a price, a kill count, a
  3	// cooldown, a title, a coordinate) changes the design, and the recompile changes config.yml (values + designer-values
  4	// hash + config_version) and the README, never a Java file. Item parameters go through the item edit path (../params.ts).
  5	// Pure: no I/O, no model call.
  6	import { applyParameterEdits, diffCompiled, type AppliedEdit, type CompiledDiff, type ParamEdit } from "../params";
  7	import type { CompileContext } from "../compile";
  8	import type { ItemDesign } from "../spec";
  9	import { compileMod, modParams, type ModCompileOk } from "./compile";
 10	import { MenuDesignSchema, QuestDesignSchema, type MenuDesign, type QuestDesign } from "./spec";
 11	import { BossDesignSchema, EncounterDesignSchema, type BossDesign, type EncounterDesign } from "../boss/spec";
 12	import { HudDesignSchema, type HudDesign } from "../hud/spec";
 13	
 14	export type GameplayMod = { items: ItemDesign[]; menus: MenuDesign[]; quests: QuestDesign[]; /** R3 bosses + encounters */ bosses?: BossDesign[]; encounters?: EncounterDesign[]; /** R4 glyph HUDs */ huds?: HudDesign[] };
 15	
 16	/** Bosses / encounters: every parameter carries its place in the design (ptr); missing objects on the way are created. */
 17	export function setAtPointer(design: Obj, ptr: (string | number)[], value: number | string): string | null {
 18	  let cur: unknown = design;
 19	  for (let i = 0; i < ptr.length - 1; i++) {
 20	    const k = ptr[i];
 21	    const o = cur as Record<string | number, unknown>;
 22	    if (o[k] === undefined) { if (typeof k === "number") return `no element ${k}`; o[k] = {}; }
 23	    cur = o[k];
 24	    if (!cur || typeof cur !== "object") return `cannot set ${ptr.join(".")}`;
 25	  }
 26	  (cur as Record<string | number, unknown>)[ptr[ptr.length - 1]] = value;
 27	  return null;
 28	}
 29	export type GameplayEditResult = { ok: true; mod: GameplayMod; applied: AppliedEdit[] } | { ok: false; errors: string[] };
 30	
 31	const camelKey = (s: string) => s.replace(/_([a-z])/g, (_, c: string) => c.toUpperCase());
 32	type Obj = Record<string, unknown>;
 33	
 34	function iconSet(icon: Obj | undefined, field: string, value: number | string): string | null {
 35	  if (!icon) return "no icon";
 36	  if (field === "name") { (icon.name as Obj).text = value; return null; }
 37	  if (field === "amount") { icon.amount = value; return null; }
 38	  const l = /^lore(\d+)$/.exec(field);
 39	  if (l) { const line = (icon.lore as Obj[] | undefined)?.[Number(l[1])]; if (!line) return "no lore line"; line.text = value; return null; }
 40	  return `unknown icon field ${field}`;
 41	}
 42	function clickSet(c: Obj, rest: string[], value: number | string): string | null {
 43	  if (rest.length === 1) return iconSet(c.icon as Obj, rest[0], value);
 44	  if (rest[0] === "cost" && rest.length === 2) { const cost = c.cost as Obj | undefined; if (!cost) return "no cost"; cost[rest[1]] = value; return null; }
 45	  const a = /^a(\d+)$/.exec(rest[0]);
 46	  if (a && rest.length === 2) { const act = (c.actions as Obj[] | undefined)?.[Number(a[1])]; if (!act) return `no action ${rest[0]}`; act[camelKey(rest[1])] = value; return null; }
 47	  return `unknown path ${rest.join(".")}`;
 48	}
 49	
 50	function setInMenu(m: Obj, rest: string[], value: number | string): string | null {
 51	  const [head, ...tail] = rest;
 52	  if (head === "title" && !tail.length) { m.title = value; return null; }
 53	  if (head === "speaker" && !tail.length) { (m.speaker as Obj).text = value; return null; }
 54	  const line = /^line(\d+)$/.exec(head);
 55	  if (line && !tail.length) { const lines = m.lines as string[]; if (Number(line[1]) >= lines.length) return "no line"; lines[Number(line[1])] = String(value); return null; }
 56	  if (head === "speaker_icon") return iconSet(m.speakerIcon as Obj, tail[0], value);
 57	  if (head === "prev" || head === "next") return iconSet(((m.list as Obj | undefined)?.[head] as Obj | undefined)?.icon as Obj, tail[0], value);
