122	      applied.push({ path: e.path, label: p.label, from: p.value, to: v });
123	      continue;
124	    }
125	    const target = p.owner === "menu" ? out.menus.find((m) => m.id === parts[1]) : out.quests.find((q) => q.id === parts[1]);
