136	  for (const q of out.quests) { const r = QuestDesignSchema.safeParse(q); if (!r.success) return { ok: false, errors: r.error.issues.slice(0, 5).map((i) => `${q.id}: ${i.path.join(".")}: ${i.message}`) }; }
