export function loadLine(p: Param, rel: string): string {
  switch (p.kind) {
    case "num": return `${p.field} = c.num(B + ${jstr(rel)}, ${jnum(p.min)}, ${jnum(p.max)});`;
    case "ticks": return `${p.field} = c.ticks(B + ${jstr(rel)}, ${p.min}L, ${p.max}L);`;
    case "int": return `${p.field} = c.integer(B + ${jstr(rel)}, ${p.min}, ${p.max});`;
    case "text": return `${p.field} = c.text(B + ${jstr(rel)}, ${p.max});`;
    case "sound": return `${p.field} = c.soundKey(B + ${jstr(rel)});`;
  }
}

type AbGen = { item: ItemDesign; ab: Ability; params: Map<string, Param>; statics: string[]; ns: string; loopN: number };
const P = (g: AbGen, rel: string) => { const p = g.params.get(rel); if (!p) throw new Error(`internal: no parameter ${rel}`); return p.field; };
export function nextConfigVersion(previous: string | undefined, valuesHash: string): number {
  if (!previous) return 1;
  const v = /^config_version:\s*(\d+)\s*$/m.exec(previous);
  const h = /^# designer-values: ([0-9a-f]{16})\s*$/m.exec(previous);
  const prev = v ? Math.max(1, Math.min(1_000_000, Number(v[1]))) : 1;
  return h && h[1] === valuesHash ? prev : prev + 1;
}

function configYml(name: string, command: string, params: Param[], version: number, valuesHash: string, seed: number): string {
  return [
    `# ${name} configuration (generated by Cyrus from the item designs).`,
    `# Values under "items" are the designs' parameters: change them here and run /${command} reload.`,
    `# Every value is checked when it is loaded: numbers are clamped to the range in their comment.`,
    `# When the mod is updated with new designer values, config_version goes up and those values are re-applied`,
    `# (your previous file is kept as config.yml.bak-v<N>). The "general" section is never overwritten.`,
    `# designer-values: ${valuesHash}`,
    `config_version: ${version}`,
    `general:`,
    `  # Seed of the random_chance conditions (java.util.Random)`,
    `  random_seed: ${seed}`,
    ...yamlTree(params),
    ``,
  ].join("\n");
}

