export function yamlTree(params: Param[]): string[] {
  type Node = { children: Map<string, Node>; param?: Param };
  const root: Node = { children: new Map() };
  for (const p of params) {
    let n = root;
    for (const seg of p.path.split(".")) { if (!n.children.has(seg)) n.children.set(seg, { children: new Map() }); n = n.children.get(seg)!; }
    n.param = p;
  }
  const out: string[] = [];
  const walk = (n: Node, ind: number) => {
    for (const [k, c] of n.children) {
      const pad = "  ".repeat(ind);
      if (c.param) {
        const p = c.param;
        const range = p.kind === "text" ? `text, max ${p.max} characters` : p.kind === "sound" ? "namespaced sound key" : `${fmtNum(p.min, p.kind)} to ${fmtNum(p.max, p.kind)}`;
        out.push(`${pad}# ${p.label} (${range})`);
        out.push(`${pad}${k}: ${p.kind === "text" || p.kind === "sound" ? ystr(String(p.value)) : fmtNum(Number(p.value), p.kind)}`);
      } else { out.push(`${pad}${k}:`); walk(c, ind + 1); }
    }
  };
  walk(root, 0);
  return out;
}

/** Hash of the designer values (the defaults Cyrus manages): config_version moves when it changes. */
export const designerValuesHash = (params: Param[]) => sha256(params.map((p) => `${p.path}=${p.kind === "text" || p.kind === "sound" ? String(p.value) : fmtNum(Number(p.value), p.kind)}`).join("\n")).slice(0, 16);
