    /** lists.<menu>: [{material, amount, price, name?}] read, checked and clamped; bad lines are skipped with a note. */
    void loadConfigList(MenuDef m, String path, CostCharger.Kind currency, Material currencyMaterial, String currencyItem) {
        List<Map<?, ?>> raw = g.designer().plugin().getConfig().getMapList(path);
        int i = -1;
        for (Map<?, ?> row : raw) {
            i++;
            if (m.entries.size() >= MAX_CONFIG_ENTRIES || m.entries.size() >= m.pageSize() * Pagination.MAX_PAGES) { g.note(path + ": more than " + m.entries.size() + " entries do not fit " + Pagination.MAX_PAGES + " pages; the rest is ignored"); bre
            Object mat = row.get("material");
            Material type = mat instanceof String ms ? Material.matchMaterial(ms) : null;
            String key = type == null ? "" : type.getKey().getKey();
            if (type == null || !type.isItem() || BANNED.matcher(key).matches()) { g.note(path + "[" + i + "]: " + mat + " cannot be sold, skipped"); continue; }
            if (currency == CostCharger.Kind.ITEM && currencyMaterial == type && currencyItem == null) { g.note(path + "[" + i + "]: a list cannot sell its own currency, skipped"); continue; }
            int amount = clampInt(row.get("amount"), 1, 64, 1, path + "[" + i + "].amount");
            double price = row.get("price") instanceof Number n ? n.doubleValue() : -1;
            CostCharger.Cost cost;
            switch (currency) {
                case ITEM: { int c = (int) Math.round(clampD(price, 1, 2304, path + "[" + i + "].price")); cost = currencyItem != null ? CostCharger.Cost.design(currencyItem, c) : CostCharger.Cost.items(currencyMaterial, c); break; }
                case XP_LEVELS: cost = CostCharger.Cost.levels((int) Math.round(clampD(price, 1, 1000, path + "[" + i + "].price"))); break;
                case ECONOMY: cost = CostCharger.Cost.money(clampD(price, 0.01, 1000000, path + "[" + i + "].price")); break;
                default: cost = CostCharger.Cost.NONE;
            }
            String name = row.get("name") instanceof String s ? clean(s, 40) : "";
            if (name.isEmpty()) name = pretty(key);
            final ItemStack give = new ItemStack(type);
            final int count = amount;
            final String label = name;
            ItemStack icon = g.icon(type, name, NamedTextColor.WHITE, List.of("x" + amount), Math.min(amount, type.getMaxStackSize()), false, null, null);
            m.entry(icon, cost, null, false, MenuDef.gives(stack(type, amount)), ctx -> { ctx.give(give, count); ctx.message("Bought " + count + " x " + label + ".", NamedTextColor.GREEN); });
        }
    }

    private static ItemStack stack(Material m, int n) { ItemStack s = new ItemStack(m); s.setAmount(Math.max(1, n)); return s; }

    private int clampInt(Object v, int min, int max, int dflt, String at) {
        if (!(v instanceof Number n)) { g.note(at + " is not a number, using " + dflt); return dflt; }
        int x = (int) Math.round(n.doubleValue());
        if (x < min || x > max) { int c = Math.max(min, Math.min(max, x)); g.note("clamped " + at + " " + x + " -> " + c); return c; }
        return x;
    }

    private double clampD(double v, double min, double max, String at) {
        if (Double.isNaN(v) || v < min || v > max) { double c = Double.isNaN(v) ? min : Math.max(min, Math.min(max, v)); g.note("clamped " + at + " " + v + " -> " + c); return c; }
        return v;
    }

