    return o as ItemStep;
  });
}
function questSteps(raw: unknown): QuestStep[] {
  need(Array.isArray(raw) && raw.length <= 40, "steps must be a list (at most 40)");
  return (raw as unknown[]).map((s) => {
    const o = (s ?? {}) as Record<string, unknown>;
    need(typeof o.k === "string" && Q_KINDS.has(o.k), "unknown simulator step");
    for (const f of ["quest", "branch", "menu"]) if (o[f] !== undefined) need(typeof o[f] === "string" && id.test(o[f] as string), `${f} is not valid`);
