    for (const f of ["count", "seconds"]) if (o[f] !== undefined) need(typeof o[f] === "number" && Number.isFinite(o[f] as number) && (o[f] as number) >= 0 && (o[f] as number) <= 7200, `${f} is out of range`);
    if (o.k === "visit") need(Array.isArray(o.pos) && o.pos.length === 3 && (o.pos as unknown[]).every((n) => typeof n === "number" && Math.abs(n) <= 3e7) && typeof o.world === "string" && /^[A-Za-z0-9_./-]{1,64}$/.test(o.world), "visit needs world and pos");
    if (o.kinds !== undefined) need(Array.isArray(o.kinds) && (o.kinds as unknown[]).every((k) => typeof k === "string" && /^[a-z]{1,12}$/.test(k)), "kinds is not valid");
    return o as QuestStep;
  });
}

