export function IssueRow({ i, tone }: { i: GpIssue; tone: "err" | "warn" }) {
  return (
    <li className={`dz-issue ${tone}`}>
      <span className="ic"><DI n={tone === "err" ? "close" : "warn"} /></span><code>{i.code}</code><span className="path" title={i.path}>{i.path}</span>
      <span className="m">{i.message}</span>
    </li>
  );
}

/** A numeric parameter stepper (or a text field) bound to a config path. */
export function ParamField({ p, was, onSet, compact }: { p: Param; was?: number | string; onSet: (v: number | string) => void; compact?: boolean }) {
  const [txt, setTxt] = useState(String(p.value));
  useEffect(() => { setTxt(String(p.value)); }, [p.value]);
  const changed = was !== undefined && String(was) !== String(p.value);
  if (p.kind === "text" || p.kind === "sound") {
    const bad = !txt.length || txt.length > p.max;
    return <input className={`dz-txt ${bad ? "err" : changed ? "chg" : ""}`} value={txt} aria-label={p.label} maxLength={p.max + 20} onChange={(e) => setTxt(e.target.value)} onBlur={() => { if (txt !== String(p.value)) onSet(txt); }} onKeyDown={(e) => { if (e.key === "Enter") (e.target as HTMLInputElement).blur(); }} style={compact ? { width: 130 } : undefined} />;
  }
  const v = Number(p.value);
  const bad = !Number.isFinite(v) || v < p.min || v > p.max;
  const span = p.max - p.min;
  const step = p.kind === "num" ? (span <= 4 ? 0.1 : span <= 40 ? 0.5 : 1) : span > 2000 ? 20 : 1;
  const set = (n: number) => onSet(p.kind === "num" ? +n.toFixed(2) : Math.round(n));
  return (
    <span className={`dz-stp ${bad ? "err" : changed ? "chg" : ""}`}>
      <button type="button" aria-label={`decrease ${p.label}`} onClick={() => set(v - step)}><DI n="minus" /></button>
      <input value={txt} inputMode="decimal" aria-label={p.label} aria-invalid={bad} onChange={(e) => setTxt(e.target.value)} onBlur={() => { const n = Number(txt); if (txt.trim() !== "" && Number.isFinite(n) && n !== v) set(n); else setTxt(String(p.value)); }} onKeyDown={(e) => { if (e.key === "Enter") (e.target as HTMLInputElement).blur(); }} />
      <button type="button" aria-label={`increase ${p.label}`} onClick={() => set(v + step)}><DI n="plus" /></button>
    </span>
  );
}
